/*
 * prog24_query_string_parser
 *
 * The original binary reads a single line from stdin, treats it as a URL‑style
 * query string (key=value pairs separated by '&'), URL‑decodes each key and
 * value and prints them as “key=value” lines.  If no line is supplied
 * (fgets returns NULL) it prints the literal string “NO_INPUT”.
 *
 * The behaviour of the original program is reproduced below.  The
 * implementation is deliberately straightforward – the original binary
 * used an obfuscated state‑machine, but the observable effect is exactly the
 * parsing described above.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define LINE_MAX   2048          /* size of the input buffer */
#define OUT_MAX    2048          /* size of the decoded key/value buffers */

/* ----------------------------------------------------------------------
 * URL‑decode a string.
 *
 *  src  – null‑terminated source string (may contain '+' and %XX escapes)
 *  dst  – buffer where the decoded string is written; must be large enough.
 *
 * The function follows the usual rules:
 *   '+'  → space
 *   %XY  → byte with hexadecimal value XY (if X and Y are hex digits)
 *   otherwise the character is copied unchanged.
 *
 * The result is NUL‑terminated.
 * ---------------------------------------------------------------------- */
static void url_decode(const char *src, char *dst)
{
    while (*src) {
        if (*src == '+') {
            *dst++ = ' ';
            src++;
        } else if (*src == '%' && isxdigit((unsigned char)src[1]) && isxdigit((unsigned char)src[2])) {
            /* Convert the two hex digits to a byte */
            char hi = src[1];
            char lo = src[2];
            int val = (isdigit((unsigned char)hi) ? hi - '0' : (tolower((unsigned char)hi) - 'a' + 10));
            val = (val << 4) + (isdigit((unsigned char)lo) ? lo - '0' : (tolower((unsigned char)lo) - 'a' + 10));
            *dst++ = (char)val;
            src += 3;
        } else {
            *dst++ = *src++;
        }
    }
    *dst = '\0';
}

/* ----------------------------------------------------------------------
 * Main program – read a line, split into key/value pairs, decode and print.
 * ---------------------------------------------------------------------- */
int main(void)
{
    static char line[LINE_MAX];
    static char key_buf[OUT_MAX];
    static char val_buf[OUT_MAX];

    /* Read a line from stdin */
    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");          /* puts adds a trailing newline */
        return 0;
    }

    /* Strip trailing newline and carriage‑return characters */
    size_t len = strlen(line);
    while (len && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
        line[--len] = '\0';
    }

    /* Parse the query string: key=value pairs separated by '&' */
    char *p = line;
    while (*p) {
        char *segment_end = strchr(p, '&');
        if (!segment_end) {
            segment_end = p + strlen(p);   /* last segment */
        }

        /* Look for '=' inside the current segment */
        char *eq = memchr(p, '=', (size_t)(segment_end - p));
        if (eq) {
            *eq = '\0';                     /* temporarily terminate key */
            url_decode(p,   key_buf);
            url_decode(eq + 1, val_buf);
        } else {
            /* No '=', treat whole segment as a key with empty value */
            url_decode(p, key_buf);
            val_buf[0] = '\0';
        }

        printf("%s=%s\n", key_buf, val_buf);

        if (*segment_end == '&')
            p = segment_end + 1;            /* move past '&' */
        else
            break;                          /* reached end of string */
    }

    return 0;
}
